        double priorityValue = lastPriorityResult.getAverageResponseTime();

        String winner = getWinnerByLowerValue(sjfValue, priorityValue);

        conclusionLabel.setText(
                "Winner in RT: " + winner + "\n\n" +
                        "SJF Average Response Time = " + format(sjfValue) + "\n" +
                        "Priority Average Response Time = " + format(priorityValue) + "\n\n" +
                        "The lower average response time is better."
        );
    }

    private boolean hasResults() {
        if (lastSjfResult == null || lastPriorityResult == null) {
            conclusionLabel.setText("Please click Run Comparison first.");
            statusLabel.setText("No comparison result yet.");
            return false;
        }

        return true;
    }

    private String getWinnerByLowerValue(double sjfValue, double priorityValue) {
        if (sjfValue < priorityValue) {
            return "SJF";
        } else if (priorityValue < sjfValue) {
            return "Priority";
        } else {
            return "Draw";
        }
    }

    private List<Process> copyProcesses(List<Process> original) {
        List<Process> copy = new ArrayList<>();

        for (Process p : original) {
            copy.add(new Process(
                    p.getPID(),
                    p.getArrivalTime(),
                    p.getBurstTime(),
                    p.getPriority(),
                    p.getBurstTime(),
                    false
            ));
        }

        return copy;
    }

    private void drawTimelineFromSjf(Sjf sjf) {
        sjfTimelineBox.getChildren().clear();

        List<String> names = sjf.getGanttProcess();
        List<Integer> times = sjf.getGantTime();

        drawTimeline(sjfTimelineBox, names, times);
    }

    private void drawTimelineFromPriority(Priority priority) {
        priorityTimelineBox.getChildren().clear();

        List<String> fullChart = priority.getGanttChart();

        if (fullChart == null || fullChart.isEmpty()) {
            return;
        }

        List<String> names = new ArrayList<>();
        List<Integer> times = new ArrayList<>();

        String current = fullChart.get(0);
        names.add(current);
        times.add(0);

        for (int i = 1; i < fullChart.size(); i++) {
            if (!fullChart.get(i).equals(current)) {
                current = fullChart.get(i);
                names.add(current);
                times.add(i);
            }
        }

        times.add(fullChart.size());

        drawTimeline(priorityTimelineBox, names, times);
    }

    private void drawTimeline(HBox container, List<String> names, List<Integer> times) {
        container.getChildren().clear();

        if (names == null || times == null || names.isEmpty() || times.size() < 2) {
            return;
        }

        for (int i = 0; i < names.size(); i++) {
            int start = times.get(i);
            int end = times.get(i + 1);

            VBox block = new VBox();
            block.getStyleClass().add("timeline-block");

            Label nameLabel = new Label(names.get(i));
            nameLabel.getStyleClass().add("timeline-name");

            Label timeLabel = new Label(start + " → " + end);
            timeLabel.getStyleClass().add("timeline-time");

            block.getChildren().addAll(nameLabel, timeLabel);

            int duration = end - start;
            block.setMinWidth(Math.max(75, duration * 28));

            container.getChildren().add(block);
        }
    }

    private void clearInputFields() {
        pidField.clear();
        arrivalField.clear();
        burstField.clear();
        priorityField.clear();
        pidField.requestFocus();
    }

    private void showError(String message) {
        statusLabel.setText(message);
    }

    private String format(double value) {
        return String.format("%.2f", value);
    }
}

package scheduler;
import model.Process;
import java.util.*;

public class Priority extends Scheduler {

    private static int maxx = 1;
    private static int boost = 1;
    private static int minPrio = 0;
    private List<Process> processes;
    private List<Process> readyQueue = new ArrayList<>();
    private Set<String> arrived = new HashSet<>();
    private Map<String, Integer> waitTicks = new HashMap<>();
    private List<String> ganttChart = new ArrayList<>();
    private boolean agingEnabled;
    private int agingVal;
    private int agingBoost;
    public Priority(List<Process> processes) {
        this(processes, true, maxx, boost);
    }
    public Priority(List<Process> processes, boolean agingEnabled, int agingThreshold, int agingBoost) {
        super(processes);
        this.processes = new ArrayList<>(processes);
        this.agingEnabled = agingEnabled;
        this.agingVal = 2;
        this.agingBoost = 1;
    }
    @Override
    public void schedule() {
        int currentTime = 0;
        Process running = null;
        while (!allFinished()) {
            addArrivedProcesses(currentTime);
            if (agingEnabled) {
                applyAging();
            }
            Process bestReady = pickBestReadyProcess();
            if (running == null) {
                if (bestReady != null) {
                    running = bestReady;
                    readyQueue.remove(running);
                    recordStart(running, currentTime);
                }
            } else if (bestReady != null && compare(bestReady, running) < 0) {
                readyQueue.add(running);
                running = bestReady;
                readyQueue.remove(running);
                recordStart(running, currentTime);
            }
            if (running == null) {
                ganttChart.add("Not found");
                currentTime++;
                continue;
            }
            ganttChart.add(running.getPID());
            running.setRemainingTime(running.getRemainingTime() - 1);
            if (running.getRemainingTime() == 0) {
                int endTime = currentTime + 1;
                running.setEndTime(endTime);
                running.setTurnaroundTime(endTime - running.getArrivalTime());
                running.setWaitingTime(
                        running.getTurnaroundTime() - running.getBurstTime()
                );
                running = null;
            }
            currentTime++;
        }
    }
    private void addArrivedProcesses(int currentTime) {
        for (Process p : processes) {
            if (p.getArrivalTime() <= currentTime
                    && p.getRemainingTime() > 0
                    && !arrived.contains(p.getPID())) {
                readyQueue.add(p);
                arrived.add(p.getPID());
                waitTicks.put(p.getPID(), 0);
            }
        }
    }
    private void applyAging() {
        for (Process p : readyQueue) {
            String id = p.getPID();
            int waited = waitTicks.getOrDefault(id, 0) + 1;
            waitTicks.put(id, waited);
            if (waited > 0 && waited % agingVal == 0) {
                int currentPriority = p.getPriority();
                int boostedPriority = Math.max(
                        minPrio,
                        currentPriority - agingBoost
                );
                if (boostedPriority < currentPriority) {
                    p.setPriority(boostedPriority);
                }
            }
        }
    }
    private Process pickBestReadyProcess() {
        if (readyQueue.isEmpty()) {
            return null;
        }
        Process best = readyQueue.get(0);
        for (int i = 1; i < readyQueue.size(); i++) {
            Process current = readyQueue.get(i);
            if (compare(current, best) < 0) {
                best = current;
            }
        }
        return best;
    }
    private int compare(Process a, Process b) {
        int pa = a.getPriority();
        int pb = b.getPriority();
        if (pa != pb)
            return Integer.compare(pa, pb);
        if (a.getArrivalTime() != b.getArrivalTime()) {
            return Integer.compare(a.getArrivalTime(), b.getArrivalTime());
        }
        if (a.getRemainingTime() != b.getRemainingTime()) {
            return Integer.compare(a.getRemainingTime(), b.getRemainingTime());
        }
        return a.getPID().compareTo(b.getPID());
    }
    private void recordStart(Process p, int currentTime) {
        if (!p.isStarted()) {
            p.setStarted(true);
            p.setStartTime(currentTime);
            p.setResponseTime(
                    currentTime - p.getArrivalTime()
            );
        }
        waitTicks.put(p.getPID(), 0);
    }
    private boolean allFinished() {
        for (Process p : processes) {
            if (p.getRemainingTime() != 0) {
                return false;
            }
        }
        return true;
    }
    @Override
    public void calculateAverages() {
        double totalWaiting = 0;
        double totalTurnaround = 0;
        double totalResponse = 0;
        int n = processes.size();
        for (Process p : processes) {
            totalWaiting += p.getWaitingTime();
            totalTurnaround += p.getTurnaroundTime();
            totalResponse += p.getResponseTime();
        }
        setAverageWaitingTime(totalWaiting / n);
        setAverageTurnaroundTime(totalTurnaround / n);
        setAverageResponseTime(totalResponse / n);
    }
    @Override
    public void makeChart() {
        // List<String> blocks = new ArrayList<>();
        // List<Integer> times = new ArrayList<>();
        // String prev = ganttChart.get(0);
        // int start = 0;
        // for (int i = 1; i < ganttChart.size(); i++) {
        //     if (!ganttChart.get(i).equals(prev)) {
        //         blocks.add(prev);
        //         times.add(start);
        //         prev = ganttChart.get(i);
        //         start = i;
        //     }
        // }
        // blocks.add(prev);
        // times.add(start);
        // times.add(ganttChart.size());
    }

    public List<String> getGanttChart() {
        return ganttChart;
    }
    public List<Integer> getGanttTimes() {
        List<Integer> times = new ArrayList<>();
        int start = 0;
        String prev = ganttChart.get(0);
        for (int i = 1; i < ganttChart.size(); i++) {
            if (!ganttChart.get(i).equals(prev)) {
                times.add(start);
                prev = ganttChart.get(i);
                start = i;
            }
        }
        times.add(start);
        times.add(ganttChart.size());
        return times ;
    }
}

